// Ohne Namensraum-Adresse: Ein <svg> in innerHTML eines HTML-Dokuments wird ohnehin als SVG gelesen.
function svgIcon(n,cls){const p=ICONS[n];if(!p){console.warn("icon",n);return ""}
return '<svg class="i '+(cls||"")+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">'+p+'</svg>'}
function drawIcons(root){(root||document).querySelectorAll("i[data-i]").forEach(el=>{el.outerHTML=svgIcon(el.dataset.i,el.className)})}
